module tb;bit clk=0;always #5 clk=~clk;bit rst=1;integer cycle=-1;
bit [0:0] monitor_axis_tkeep;bit monitor_axis_tvalid=0,monitor_axis_tready=0,monitor_axis_tlast=0;wire [15:0] frame_len;wire frame_len_valid;
axis_frame_len #(.DATA_WIDTH(8),.KEEP_ENABLE(0),.KEEP_WIDTH(1)) dut(.*);
wire accept=monitor_axis_tvalid && monitor_axis_tready;wire finish=accept && monitor_axis_tlast;
integer acc_bytes=0;bit prev_complete=0;
wire [31:0] beat_bytes=32'd1;
always @(posedge clk) begin if(rst) begin acc_bytes<=0;prev_complete<=0;end else begin prev_complete<=finish;if(accept) begin if(monitor_axis_tlast) acc_bytes<=0;else acc_bytes<=acc_bytes+beat_bytes;end end end
adjacent_length: assert property (@(posedge clk) disable iff(rst) (finish && prev_complete) |=> (frame_len_valid && frame_len == $past(acc_bytes+beat_bytes))) else $display("ASSERT_FAIL adjacent_length cycle=%0d",$sampled(cycle));
always @(posedge clk) if(!rst && (finish && prev_complete)) $display("TRIGGER adjacent_length cycle=%0d",cycle);
separated_length: assert property (@(posedge clk) disable iff(rst) (finish && !prev_complete) |=> (frame_len_valid && frame_len == $past(acc_bytes+beat_bytes))) else $display("ASSERT_FAIL separated_length cycle=%0d",$sampled(cycle));
always @(posedge clk) if(!rst && (finish && !prev_complete)) $display("TRIGGER separated_length cycle=%0d",cycle);
all_length: assert property (@(posedge clk) disable iff(rst) (finish) |=> (frame_len_valid && frame_len == $past(acc_bytes+beat_bytes))) else $display("ASSERT_FAIL all_length cycle=%0d",$sampled(cycle));
always @(posedge clk) if(!rst && (finish)) $display("TRIGGER all_length cycle=%0d",cycle);
single_beat_length: assert property (@(posedge clk) disable iff(rst) (finish) |=> (frame_len_valid && frame_len == $past(beat_bytes))) else $display("ASSERT_FAIL single_beat_length cycle=%0d",$sampled(cycle));
always @(posedge clk) if(!rst && (finish)) $display("TRIGGER single_beat_length cycle=%0d",cycle);
never_length: assert property (@(posedge clk) disable iff(rst) (finish && acc_bytes<0) |=> (frame_len_valid && frame_len == $past(acc_bytes+beat_bytes))) else $display("ASSERT_FAIL never_length cycle=%0d",$sampled(cycle));
always @(posedge clk) if(!rst && (finish && acc_bytes<0)) $display("TRIGGER never_length cycle=%0d",cycle);
valid_check: assert property (@(posedge clk) disable iff(rst) (1'b1) |=> (frame_len_valid == $past(finish))) else $display("ASSERT_FAIL valid_check cycle=%0d",$sampled(cycle));
always @(posedge clk) if(!rst && (1'b1)) $display("TRIGGER valid_check cycle=%0d",cycle);
initial begin $dumpfile("wave.vcd");$dumpvars(0,tb);
